- = അലിഫ്, ലാം, മീം. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = അവർ തങ്ങളുടെ രക്ഷിതാവിങ്കൽ നിന്നുള്ള നേർവഴിയിലാണ്; അവർ തന്നെയാണ് വിജയികൾ. 2:5; 31:5
- = ഇസ്രായീൽ സന്തതികളേ, ഞാൻ നിങ്ങൾക്ക് നൽകിയ എന്റെ അനുഗ്രഹവും ഞാൻ നിങ്ങളെ ലോകരെക്കാൾ (ജനങ്ങളെക്കാൾ) ഉയർത്തിയതും ഓർമ്മിക്കുക. 2:47; 2:122
- = അത് കഴിഞ്ഞുപോയ ഒരു സമൂഹമാണ്. അവർക്ക് അവർ സമ്പാദിച്ചതും നിങ്ങൾക്ക് നിങ്ങൾ സമ്പാദിച്ചതും. അവർ ചെയ്തുകൊണ്ടിരുന്നതിനെക്കുറിച്ച് നിങ്ങളോട് ചോദിക്കപ്പെടുകയില്ല. 2:134; 2:141
- = അവർ അതിൽ എന്നെന്നും കഴിയും. ശിക്ഷ അവർക്ക് ലഘൂകരിക്കപ്പെടുകയില്ല; അവർക്ക് അവധി നൽകപ്പെടുകയുമില്ല. 2:162; 3:88
- = എന്നാൽ അതിനുശേഷം പശ്ചാത്തപിക്കുകയും സ്വയം പരിഷ്കരിക്കുകയും ചെയ്യുന്നവർ ഒഴികെ. തീർച്ചയായും അല്ലാഹു ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു. 3:89; 24:5
- = എന്നാൽ അവിശ്വസിക്കുകയും നമ്മുടെ ദൃഷ്ടാന്തങ്ങളെ നിഷേധിക്കുകയും ചെയ്തവർ – അവർ നരകക്കാർ തന്നെ. 5:10; 5:86
- = അവരുടെ രക്ഷിതാവിന്റെ ദൃഷ്ടാന്തങ്ങളിൽ നിന്ന് ഒരു ദൃഷ്ടാന്തവും അവരിലേക്ക് വരുന്നില്ല; അതിൽ നിന്ന് അവർ മുഖം തിരിച്ചുകളയുന്നു. 6:4; 36:46
- = നിനക്ക് മുമ്പും ദൂതന്മാർ പരിഹസിക്കപ്പെട്ടിട്ടുണ്ട്. എന്നാൽ പരിഹസിച്ചവരെ, അവർ പരിഹസിച്ചുകൊണ്ടിരുന്നത് തന്നെ വലയം ചെയ്തു. 6:10; 21:41
- = പറയുക: "ഞാൻ എന്റെ രക്ഷിതാവിനെ അനുസരിക്കാതിരുന്നാൽ, മഹത്തായ ദിനത്തിലെ ശിക്ഷയെ ഞാൻ ഭയപ്പെടുന്നു." 6:15; 39:13
- = അപ്പോൾ ഭൂകമ്പം അവരെ പിടികൂടി; അവർ തങ്ങളുടെ വീടുകളിൽ കമിഴ്ന്നു വീണ് (മരിച്ച്) കിടന്നു. 7:78; 7:91
- = അങ്ങനെ അദ്ദേഹം (മൂസാ) തന്റെ വടി എറിഞ്ഞു; അതാ അത് വ്യക്തമായ ഒരു പാമ്പായിത്തീർന്നു. 7:107; 26:32
- = അദ്ദേഹം തന്റെ കൈ പുറത്തെടുത്തു; അതാ അത് നോക്കുന്നവർക്ക് വെളുത്ത് (പ്രകാശമാനമായി) തീർന്നു. 7:108; 26:33
- = അവർ പറഞ്ഞു: "ലോകങ്ങളുടെ രക്ഷിതാവിൽ ഞങ്ങൾ വിശ്വസിച്ചിരിക്കുന്നു." 7:121; 26:47
- = മൂസായുടെയും ഹാറൂന്റെയും രക്ഷിതാവ്. 7:122; 26:48
- = ഞാൻ അവർക്ക് അവധി നൽകും. തീർച്ചയായും എന്റെ തന്ത്രം ഉറച്ചതാണ്. 7:183; 68:45
- = അവൻ തന്റെ ദൂതനെ സന്മാർഗവും സത്യമതവും സഹിതം അയച്ചു. ബഹുദൈവവിശ്വാസികൾക്ക് അനിഷ്ടമുണ്ടെങ്കിലും, അതിനെ എല്ലാ മതങ്ങൾക്കും മീതെ വിജയിപ്പിക്കുന്നതിനായി. 9:33; 61:9
- = നബിയേ, സത്യനിഷേധികളോടും കപടവിശ്വാസികളോടും സമരം ചെയ്യുക; അവരോട് കർശനമായി പെരുമാറുക. അവരുടെ സങ്കേതം നരകമാകുന്നു; എത്ര ചീത്തയായ മടക്കം! 9:73; 66:9
- = അവർ പറയുന്നു: "നിങ്ങൾ സത്യവാന്മാരാണെങ്കിൽ ഈ വാഗ്ദാനം എപ്പോഴാണ് (വരുക)?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = തീർച്ചയായും നാം മൂസായെ നമ്മുടെ ദൃഷ്ടാന്തങ്ങളോടും വ്യക്തമായ അധികാരത്തോടും കൂടി അയച്ചു. 11:96; 40:23
- = തീർച്ചയായും നാം മൂസായ്ക്ക് വേദഗ്രന്ഥം നൽകി; എന്നാൽ അതിൽ അഭിപ്രായവ്യത്യാസമുണ്ടായി. നിന്റെ രക്ഷിതാവിങ്കൽ നിന്ന് ഒരു വാക്ക് മുൻകൂട്ടി വന്നില്ലായിരുന്നുവെങ്കിൽ, അവർക്കിടയിൽ തീർപ്പുണ്ടാകുമായിരുന്നു. തീർച്ചയായും അവർ അതിൽ സംശയത്തിലാണ്. 11:110; 41:45
- = അത് അല്ലാഹുവിന് പ്രയാസമുള്ളതല്ല. 14:20; 35:17
- = "ഞാൻ അവനെ രൂപപ്പെടുത്തി, എന്റെ ആത്മാവിൽ നിന്ന് അവനിൽ ഊതുമ്പോൾ, നിങ്ങൾ അവന് സാഷ്ടാംഗം ചെയ്ത് വീഴുക." 15:29; 38:72
- = അപ്പോൾ മലക്കുകൾ മുഴുവൻ ഒന്നിച്ചു സാഷ്ടാംഗം ചെയ്തു. 15:30; 38:73
- = (അല്ലാഹു) അരുൾ ചെയ്തു: "എങ്കിൽ അവിടെ നിന്ന് പുറത്തുപോകുക; തീർച്ചയായും നീ ഭ്രഷ്ടനാണ്." 15:34; 38:77
- = (ഇബ്ലീസ്) പറഞ്ഞു: "എന്റെ രക്ഷിതാവേ, അപ്പോൾ അവർ ഉയിർത്തെഴുന്നേൽക്കപ്പെടുന്ന ദിനം വരെ എനിക്ക് അവധി തരേണമേ." 15:36; 38:79
- = (അല്ലാഹു) അരുൾ ചെയ്തു: "എങ്കിൽ തീർച്ചയായും നീ അവധി ലഭിച്ചവരുടെ കൂട്ടത്തിലാണ്." 15:37; 38:80
- = നിശ്ചയിക്കപ്പെട്ട സമയത്തിന്റെ ദിനം വരെ." 15:38; 38:81
- = അവരിൽ നിന്റെ തെരഞ്ഞെടുക്കപ്പെട്ട ദാസന്മാരൊഴികെ. 15:40; 38:83
- = തീർച്ചയായും ധർമ്മനിഷ്ഠയുള്ളവർ സ്വർഗത്തോട്ടങ്ങളിലും അരുവികളിലും ആയിരിക്കും. 15:45; 51:15
- = അദ്ദേഹം (ഇബ്രാഹീം) ചോദിച്ചു: "എന്നാൽ ദൂതന്മാരേ, നിങ്ങളുടെ കാര്യമെന്താണ്?" 15:57; 51:31
- = അവർ പറഞ്ഞു: "ഞങ്ങൾ കുറ്റവാളികളായ ഒരു ജനതയിലേക്ക് അയക്കപ്പെട്ടിരിക്കുന്നു." 15:58; 51:32
- = വിശ്വസിക്കുകയും തങ്ങളുടെ വിശ്വാസത്തെ അക്രമവുമായി കലർത്താതിരിക്കുകയും ചെയ്തവർ – അവർക്ക് സുരക്ഷയുണ്ട്; അവർ സന്മാർഗ്ഗം പ്രാപിച്ചവരുമാണ്. 16:42; 29:59
- = നാം അവർക്ക് നൽകിയതിനെ അവർ നിഷേധിക്കുന്നതിന്. എന്നാൽ സുഖിച്ചുകൊള്ളുക; വൈകാതെ നിങ്ങൾ അറിയും. 16:55; 30:34
- = പിന്നീട് അദ്ദേഹം (ദുൽഖർനൈൻ) ഒരു പാത പിന്തുടർന്നു. 18:89; 18:92
- = ഫിർഔനിലേക്ക് പോകുക; തീർച്ചയായും അവൻ അതിക്രമം കാണിച്ചു. 20:24; 79:17
- = അവർ തങ്ങളുടെ ലൈംഗികാവയവങ്ങളെ കാത്തുസൂക്ഷിക്കുന്നവരാണ്. 23:5; 70:29
- = തങ്ങളുടെ ഭാര്യമാരോടോ വലതു കൈകൾക്ക് ഉടമസ്ഥതയുള്ളവരോടോ (ബന്ധപ്പെടുന്നത്) ഒഴികെ; എന്തെന്നാൽ അവർ നിന്ദ്യരല്ല. 23:6; 70:30
- = എന്നാൽ അതിനപ്പുറം ആഗ്രഹിക്കുന്നവരാരോ – അവർ അതിക്രമികൾ തന്നെ. 23:7; 70:31
- = അവർ തങ്ങളുടെ വിശ്വാസങ്ങളെയും കരാറുകളെയും കാത്തുസൂക്ഷിക്കുന്നവരാണ്. 23:8; 70:32
- = (നൂഹ്) പറഞ്ഞു: "എന്റെ രക്ഷിതാവേ, അവർ എന്നെ നിഷേധിച്ചതിനാൽ എനിക്ക് സഹായം നൽകേണമേ." 23:26; 23:39
- = ത്വാ, സീൻ, മീം. 26:1; 28:1
- = ഇത് വ്യക്തമായ വേദഗ്രന്ഥത്തിന്റെ വചനങ്ങളാകുന്നു. 26:2; 28:2
- = തീർച്ചയായും ഇതിൽ ഒരു ദൃഷ്ടാന്തമുണ്ട്; എന്നാൽ അവരിൽ ഭൂരിഭാഗവും വിശ്വസിക്കുന്നവരല്ല. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = തീർച്ചയായും നിന്റെ രക്ഷിതാവ് – അവൻ തന്നെ പ്രതാപിയും കരുണാനിധിയും. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ബാക്കിയുള്ളവരെ നാം മുക്കി നശിപ്പിച്ചു. 26:66; 37:82
- = തീർച്ചയായും ഞാൻ നിങ്ങൾക്ക് വിശ്വസ്തനായ ദൂതനാകുന്നു. 26:107; 26:125; 26:143; 26:162; 26:178
- = എന്നാൽ അല്ലാഹുവെ സൂക്ഷിക്കുകയും എന്നെ അനുസരിക്കുകയും ചെയ്യുക. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = ഇതിന് ഞാൻ നിങ്ങളോട് യാതൊരു പ്രതിഫലവും ആവശ്യപ്പെടുന്നില്ല; എന്റെ പ്രതിഫലം ലോകരക്ഷിതാവിന്റെ പക്കൽ മാത്രമാണ്. 26:109; 26:127; 26:145; 26:164; 26:180
- = സ്വർഗത്തോട്ടങ്ങളിലും അരുവികളിലും. 26:147; 44:52
- = അവർ പറഞ്ഞു: "നീ ജാലവിദ്യയ്ക്ക് വിധേയനായവരുടെ കൂട്ടത്തിലാണ്." 26:153; 26:185
- = എന്നാൽ അദ്ദേഹത്തിന്റെ ഭാര്യയൊഴികെ – അവൾ പിന്നിൽ വീണവരുടെ കൂട്ടത്തിലായിരിക്കണമെന്ന് നാം വിധിച്ചു. 26:171; 37:135
- = പിന്നീട് ബാക്കിയുള്ളവരെ നാം നശിപ്പിച്ചു. 26:172; 37:136
- = അവരുടെ മേൽ നാം (കല്ല്) മഴ പെയ്യിച്ചു; അപ്പോൾ താക്കീത് ലഭിച്ചവർക്ക് ലഭിച്ച മഴ എത്ര ചീത്ത! 26:173; 27:58
- = എന്നിട്ടും അവർ നമ്മുടെ ശിക്ഷ ത്വരിതപ്പെടുത്താനാണോ ആവശ്യപ്പെടുന്നത്? 26:204; 37:176
- = അവർ നമസ്കാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും പരലോകത്തിൽ ഉറച്ച വിശ്വാസമുള്ളവരുമാണ്. 27:3; 31:4
- = (ഓർമ്മിക്കുക) അവൻ അവരെ വിളിക്കുകയും "നിങ്ങൾ പറഞ്ഞുകൊണ്ടിരുന്ന എന്റെ 'പങ്കാളികൾ' എവിടെയാണ്?" എന്ന് ചോദിക്കുകയും ചെയ്യുന്ന ആ ദിനത്തെ. 28:62; 28:74
- = നമ്മുടെ പൂർവ്വികരും (ഉയിർത്തെഴുന്നേൽക്കുമോ)? 37:17; 56:48
- = അവർ അന്യോന്യം അടുത്തുവന്ന് പരസ്പരം ചോദ്യം ചെയ്യും. 37:27; 52:25
- = എന്നാൽ (അവർ) അല്ലാഹുവിന്റെ തെരഞ്ഞെടുക്കപ്പെട്ട ദാസന്മാർ. 37:40; 37:74; 37:128; 37:160
- = അനുഗ്രഹങ്ങളുടെ സ്വർഗത്തോട്ടങ്ങളിൽ. 37:43; 56:12
- = പിൽക്കാല തലമുറകൾക്കിടയിൽ നാം അദ്ദേഹത്തിന്റെ (നന്മയുടെ) സ്മരണ നിലനിർത്തി: 37:78; 37:108; 37:129
- = തീർച്ചയായും നാം ഇപ്രകാരം സൽകർമ്മികൾക്ക് പ്രതിഫലം നൽകുന്നു. 37:80; 37:121; 37:131; 77:44
- = തീർച്ചയായും അദ്ദേഹം നമ്മുടെ വിശ്വാസികളായ ദാസന്മാരിൽ പെട്ടവനായിരുന്നു. 37:81; 37:111; 37:132
- = നിങ്ങൾക്കെന്തുപറ്റി? എങ്ങനെയാണ് നിങ്ങൾ വിധിക്കുന്നത്? 37:154; 68:36
- = ഇത് (ഖുർആൻ) ലോകർക്കുള്ള ഒരു ഉൽബോധനമല്ലാതെ മറ്റൊന്നുമല്ല. 38:87; 81:27
- = വേദഗ്രന്ഥത്തിന്റെ അവതരണം പ്രതാപിയും യുക്തിമാനുമായ അല്ലാഹുവിങ്കൽ നിന്നാണ്. 39:1; 45:2; 46:2
- = ഹാ, മീം. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = വ്യക്തമായ വേദഗ്രന്ഥത്തെ സാക്ഷിയാക്കി. 43:2; 44:2
- = എന്നാൽ അവരെ വിട്ടേക്കുക; അവർക്ക് വാഗ്ദാനം ചെയ്യപ്പെട്ട അവരുടെ ആ ദിനത്തെ കണ്ടുമുട്ടുന്നതുവരെ അവർ വ്യർത്ഥ സംസാരത്തിലും വിനോദത്തിലും മുഴുകി കഴിയട്ടെ. 43:83; 70:42
- = (അവരോട് പറയപ്പെടും): "നിങ്ങൾ പ്രവർത്തിച്ചിരുന്നതിന്റെ ഫലമായി തൃപ്തിയോടെ ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്യുക." 52:19; 77:43
- = അതല്ല, നീ അവരോട് പ്രതിഫലം ആവശ്യപ്പെടുന്നുവോ? അങ്ങനെ അവർ കടത്തിന്റെ ഭാരത്തിൽ അമർന്നിരിക്കുകയാണോ? 52:40; 68:46
- = അതല്ല, അവർക്ക് അദൃശ്യത്തിന്റെ അറിവുണ്ടോ, അങ്ങനെ അവർ അത് (പകർത്തി) എഴുതുന്നു? 52:41; 68:47
- = എന്റെ ശിക്ഷയും എന്റെ താക്കീതുകളും എത്ര (ഭയങ്കരമായിരുന്നു)! 54:16; 54:21; 54:30
- = തീർച്ചയായും നാം ഖുർആനെ ഓർമ്മക്കായി എളുപ്പമാക്കിയിരിക്കുന്നു. ഓർമ്മിക്കാൻ ആരെങ്കിലുമുണ്ടോ? 54:17; 54:22; 54:32; 54:40
- = അപ്പോൾ നിങ്ങളുടെ രക്ഷിതാവിന്റെ അനുഗ്രഹങ്ങളിൽ ഏതിനെയാണ് നിങ്ങൾ നിഷേധിക്കുക? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = പൂർവ്വികരിൽ ഒരു വലിയ സംഘം. 56:13; 56:39
- = ഞങ്ങൾ (വിളവെടുപ്പിൽ നിന്ന്) വഞ്ചിക്കപ്പെട്ടു? 56:67; 68:27
- = അതിനാൽ നിന്റെ മഹാനായ രക്ഷിതാവിന്റെ നാമത്തെ മഹത്വീകരിക്കുക. 56:74; 56:96; 69:52
- = ഇത് ലോകരക്ഷിതാവിങ്കൽ നിന്നുള്ള അവതരണമാണ്. 56:80; 69:43
- = ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും അല്ലാഹുവെ സ്തുതിക്കുന്നു; അവൻ പ്രതാപിയും യുക്തിമാനും ആകുന്നു. 59:1; 61:1
- = നമ്മുടെ വചനങ്ങൾ അവനോട് ഓതിക്കേൾപ്പിക്കുമ്പോൾ, അവൻ പറയുന്നു: "പൂർവ്വികരുടെ കെട്ടുകഥകൾ!" 68:15; 83:13
- = അപ്പോൾ അവൻ സുഖകരമായ ജീവിതത്തിലായിരിക്കും. 69:21; 101:7
- = ഉയർന്ന സ്വർഗത്തോട്ടത്തിൽ. 69:22; 88:10
- = എളിയവർക്ക് ഭക്ഷണം നൽകാൻ അവൻ പ്രോത്സാഹിപ്പിക്കുന്നില്ല. 69:34; 107:3
- = തീർച്ചയായും ഇത് (ഖുർആൻ) ഒരു ആദരണീയ ദൂതന്റെ (ജിബ്രീലിന്റെ) വചനമാകുന്നു. 69:40; 81:19
- = തീർച്ചയായും ഇത് ഒരു ഉൽബോധനമാകുന്നു; അതിനാൽ ആഗ്രഹിക്കുന്നവൻ തന്റെ രക്ഷിതാവിലേക്ക് ഒരു പാത സ്വീകരിച്ചുകൊള്ളട്ടെ. 73:19; 76:29
- = ആഗ്രഹിക്കുന്നവൻ അത് ഓർമ്മിക്കുകയും ചെയ്യട്ടെ. 74:55; 80:12
- = ആ ദിനത്തിൽ നിഷേധിച്ചവർക്ക് കേട്! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = തീർച്ചയായും പുണ്യവാന്മാർ സുഖത്തിലായിരിക്കും. 82:13; 83:22
- = അത് എഴുതപ്പെട്ട ഒരു രജിസ്റ്ററാണ്. 83:9; 83:20
- = (സ്വർഗത്തിൽ) മെത്തകളിൽ ഇരുന്നു (അവർ) നോക്കിക്കൊണ്ടിരിക്കും. 83:23; 83:35
- = അത് (ആകാശം) തന്റെ രക്ഷിതാവിനെ അനുസരിച്ചു; അത് അങ്ങനെ ചെയ്യേണ്ടതായിരുന്നു. 84:2; 84:5
- = ഞാൻ നിങ്ങൾ ആരാധിക്കുന്നതിനെ ആരാധിക്കുന്നവനല്ല. 109:3; 109:5
