- അല്ലാഹുവെക്കൂടാതെ ഒന്നിനെയും ആരാധിക്കരുത്; തീർച്ചയായും, ഞാൻ നിങ്ങൾക്ക് ആ മഹാദിനത്തിലെ ശിക്ഷയെ ഭയപ്പെടുന്നു. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- അത് അദൃശ്യവിവരങ്ങളിൽ പെട്ടതാണ്, അത് നിനക്ക് നാം ബോധനം നൽകുന്നു; അവർ തീരുമാനമെടുക്കുമ്പോൾ നീ അവരുടെ അടുക്കൽ ഉണ്ടായിരുന്നില്ല. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- നിങ്ങളുടെ രക്ഷിതാവിങ്കൽ നിന്ന് നിങ്ങളിൽത്തന്നെയുള്ള ഒരു മനുഷ്യൻ മുഖേന ഉൽബോധനം വന്നതിൽ നിങ്ങൾ ആശ്ചര്യപ്പെടുകയാണോ, അവൻ നിങ്ങളെ താക്കീത് ചെയ്യാൻ? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- പറയുക: "അല്ലാഹുവെക്കൂടാതെ നിങ്ങൾ വിളിച്ചു പ്രാർത്ഥിക്കുന്നവരെ ഞാൻ ആരാധിക്കുന്നത് വിലക്കപ്പെട്ടിരിക്കുന്നു." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- സ്വന്തം ഭാര്യമാരെയോ വലതുകൈകൾ ഉടമപ്പെടുത്തിയവരെയോ ഒഴികെ, കാരണം അവർ ആക്ഷേപാർഹരല്ല. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- അല്ലാഹു രാത്രിയെ പകലിലേക്കും പകലിനെ രാത്രിയിലേക്കും പ്രവേശിപ്പിക്കുന്നു. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- തീ, അവൻ തന്റെ കുടുംബത്തോട് പറഞ്ഞു: "നിങ്ങൾ കാത്തിരിക്കുക, ഞാൻ ഒരു തീ കണ്ടു, ഒരുപക്ഷേ ഞാൻ അതിൽ നിന്ന് നിങ്ങൾക്ക് എന്തെങ്കിലും കൊണ്ടുവന്നേക്കാം." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- അവൻ പറഞ്ഞു: "ഞാൻ അവനെക്കാൾ ഉത്തമൻ; എന്നെ നീ അഗ്നിയിൽ നിന്ന് സൃഷ്ടിച്ചു, അവനെ കളിമണ്ണിൽ നിന്നും സൃഷ്ടിച്ചു." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- അവരോട് പറയപ്പെടുമ്പോൾ: "അല്ലാഹു അവതരിപ്പിച്ചതിലേക്കും ദൂതന്റെ അടുത്തേക്കും വരൂ." (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- അവർക്കുവേണ്ടി നീ ദുഃഖിക്കുകയും അവരുടെ കുതന്ത്രങ്ങളെപ്പറ്റി മനസ്സിടുങ്ങുകയും ചെയ്യരുത്. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- അല്ലാഹു നിനക്ക് എന്തെങ്കിലും ദോഷം വരുത്തിയാൽ, അവനല്ലാതെ അത് നീക്കാൻ ആരുമില്ല, അവൻ. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- അവർക്ക് മുമ്പുള്ള തലമുറകൾ, അവർ അവരുടെ വാസസ്ഥലങ്ങളിൽ നടന്നു; തീർച്ചയായും അതിൽ ദൃഷ്ടാന്തങ്ങളുണ്ട്. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- അവരുടെ ഹൃദയങ്ങളിൽ അവർ അത് ഗ്രഹിക്കാതിരിക്കാൻ മറകൾ വെച്ചു, അവരുടെ ചെവികളിൽ ഭാരവും, അവർ. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- അവരുടെ ദൂതന്മാർ വ്യക്തമായ തെളിവുകളുമായി അവരുടെ അടുത്ത് വന്നു, എന്നാൽ അല്ലാഹു അവരോട് അക്രമം ചെയ്യുന്നവനല്ല, പക്ഷേ അവർ തങ്ങളോടുതന്നെ അക്രമം ചെയ്തു. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ഭൂമിയിൽ, അല്ലാഹുവിനെക്കൂടാതെ നിങ്ങൾക്ക് യാതൊരു രക്ഷാധികാരിയും സഹായിയുമില്ല. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- പിന്നീട് നിങ്ങളെ അദൃശ്യവും ദൃശ്യവും അറിയുന്നവന്റെ അടുത്തേക്ക് മടക്കപ്പെടും, അപ്പോൾ നിങ്ങൾ ചെയ്തുകൊണ്ടിരുന്നതിനെപ്പറ്റി അവൻ നിങ്ങളെ അറിയിക്കും. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- രാത്രി, നിങ്ങൾ അതിൽ വിശ്രമിക്കാൻ, പകൽ, നിങ്ങൾ കാണാൻ; തീർച്ചയായും അതിൽ ചിന്തിക്കുന്ന ജനങ്ങൾക്ക് ദൃഷ്ടാന്തങ്ങളുണ്ട്. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- നിന്റെ രക്ഷിതാവിൽ നിന്ന് നിനക്ക് അവതരിപ്പിക്കപ്പെട്ടത് അവരിൽ പലർക്കും അതിക്രമവും അവിശ്വാസവും വർദ്ധിപ്പിക്കും. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- അവൻ പറഞ്ഞു: "എന്റെ ജനങ്ങളേ! നിങ്ങൾ എന്തു പറയുന്നു, ഞാൻ എന്റെ രക്ഷിതാവിങ്കൽ നിന്ന് വ്യക്തമായ തെളിവിലാണെങ്കിൽ, അവൻ എനിക്ക് നൽകിയിട്ടുണ്ടെങ്കിൽ." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- അവർ പറയുന്നു: "അവന്റെ രക്ഷിതാവിങ്കൽ നിന്ന് എന്തുകൊണ്ട് ഒരു ദൃഷ്ടാന്തം അവന് അവതരിപ്പിക്കപ്പെട്ടില്ല?" പറയുക: "തീർച്ചയായും." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- അല്ലാഹുവിങ്കൽ നിന്ന് മടക്കമില്ലാത്ത ഒരു ദിനം വരുന്നതിന് മുമ്പ്. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- അത് അല്ലാഹുവിന്റെ അനുഗ്രഹമാണ്, അവൻ അത് താൻ ഇച്ഛിക്കുന്നവർക്ക് നൽകുന്നു, അല്ലാഹു മഹത്തായ അനുഗ്രഹത്തിന്റെ ഉടമയാണ്. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- തീർച്ചയായും, കന്നുകാലികളിൽ നിങ്ങൾക്ക് ഒരു പാഠമുണ്ട്; അവയുടെ ഉദരങ്ങളിലുള്ളതിൽ നിന്ന് ഞങ്ങൾ നിങ്ങൾക്ക് കുടിക്കാൻ നൽകുന്നു. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- അത് അവരുടെ രക്ഷിതാവിങ്കൽ നിന്നുള്ള സത്യമാണെന്നും, അല്ലാഹു അവർ ചെയ്യുന്നതിനെപ്പറ്റി അശ്രദ്ധനല്ലെന്നും. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- അവരുടെ മുന്നിലും പിന്നിലും, അല്ലാഹുവെക്കൂടാതെ നിങ്ങൾ ആരെയും ആരാധിക്കരുത്. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- തീർച്ചയായും, നിങ്ങൾ സ്ത്രീകളെ വിട്ട് പുരുഷന്മാരോട് കാമത്തോടെ സമീപിക്കുന്നു; അല്ല, നിങ്ങൾ അതിക്രമികളായ ജനമാണ്. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- അവർ അതിൽ ശാശ്വതമായി കഴിയും, ആകാശങ്ങളും ഭൂമിയും നിലനിൽക്കുന്നിടത്തോളം, നിന്റെ രക്ഷിതാവ് ഇച്ഛിക്കുന്നതൊഴികെ. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളവർ, അല്ലാഹു ഇച്ഛിക്കുന്നവരൊഴികെ. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- അവർക്ക് അവിടെ സ്വർണ്ണവളകളും മുത്തുകളും അണിയിക്കും, അവരുടെ വസ്ത്രങ്ങൾ പട്ടായിരിക്കും. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- അവൻ ആകാശത്ത് നിന്ന് വെള്ളം ഇറക്കി, അതുവഴി നിങ്ങൾക്ക് ആഹാരമായി കായ്കനികൾ ഉൽപ്പാദിപ്പിച്ചു. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
