- അവരുടെ ഹൃദയങ്ങളിൽ അവർ അത് ഗ്രഹിക്കാതിരിക്കാൻ മറകൾ വെച്ചു, അവരുടെ ചെവികളിൽ ഭാരവും. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- അവൻ ഉയിർത്തെഴുന്നേൽപ്പിന്റെ നാളിൽ അവർക്കിടയിൽ, അവർ ഭിന്നിച്ചുകൊണ്ടിരുന്നതിൽ, തീർപ്പുകൽപിക്കും. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- അവൻ പറഞ്ഞു: "എന്റെ ജനങ്ങളേ! നിങ്ങൾ എന്തു പറയുന്നു, ഞാൻ എന്റെ രക്ഷിതാവിങ്കൽ നിന്ന് വ്യക്തമായ തെളിവിലാണെങ്കിൽ?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- അത് നിങ്ങളുടെ കൈകൾ മുൻകൂട്ടി ചെയ്തതിന്റെ ഫലമാണ്, അല്ലാഹു ദാസന്മാരോട് അക്രമം ചെയ്യുന്നവനല്ല. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- അവർക്ക് ഐഹികത്തിൽ അപമാനവും പരലോകത്തിൽ വലിയ ശിക്ഷയുമുണ്ട്. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം, അല്ലാഹു രക്ഷാധികാരിയായി മതിയാകും. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- വിശ്വസിക്കുകയും സൽക്കർമ്മങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്തവരൊഴികെ; അവർക്ക് ഒരിക്കലും അവസാനിക്കാത്ത പ്രതിഫലമുണ്ട്. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- നീ എനിക്ക് ഒരു പങ്കുകാരനെ ഉണ്ടാക്കരുത്, അത് നിനക്ക് അറിയില്ല; അവരെ അനുസരിക്കരുത്. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- തീർച്ചയായും, ഇത് ഒരു ഉൽബോധനമാണ്; ആരെങ്കിലും ഇച്ഛിക്കുന്നുവെങ്കിൽ, അവൻ തന്റെ രക്ഷിതാവിലേക്കുള്ള മാർഗ്ഗം സ്വീകരിക്കട്ടെ. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ആർ നന്ദി കാണിക്കുന്നുവോ, അവൻ സ്വന്തം നന്മയ്ക്കായി നന്ദി കാണിക്കുന്നു; ആർ നന്ദികെട്ടവനാകുന്നുവോ. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- നമസ്കാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും പരലോകത്തെ ഉറപ്പായി വിശ്വസിക്കുകയും ചെയ്യുന്നവർ. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ഇബ്രാഹീം, ഇസ്മാഈൽ, ഇസ്ഹാഖ്, യഅ്ഖൂബ്, ഗോത്രങ്ങൾ, മൂസാ, ഈസാ എന്നിവർക്ക് നൽകപ്പെട്ടത്. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- സംഘങ്ങളായി, അവർ അതിന്റെ അടുത്ത് വരുമ്പോൾ, അതിന്റെ വാതിലുകൾ തുറക്കപ്പെടും, അതിന്റെ കാവൽക്കാർ അവരോട് പറയും. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- നിങ്ങളുടെ ആണയിടലുകളിലെ വെറും വാക്കുകൾക്ക് അല്ലാഹു നിങ്ങളെ പിടിക്കുകയില്ല, പക്ഷേ നിങ്ങളുടെ ഹൃദയങ്ങൾ സമ്പാദിച്ചതിന് പിടിക്കും. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- കാരുണ്യം, അവർ അതിൽ സന്തോഷിക്കുന്നു; അവരുടെ കൈകൾ മുൻകൂട്ടി ചെയ്തതിനാൽ അവർക്ക് ദോഷം ബാധിച്ചാൽ. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- താഴ്ഭാഗത്ത് നദികൾ ഒഴുകുന്ന സ്വർഗീയാരാമങ്ങൾ, അവയിൽ അവർ ശാശ്വതമായി കഴിയും, പ്രവർത്തിക്കുന്നവരുടെ പ്രതിഫലം എത്ര മഹത്തരം! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- അല്ലാഹു ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അറിയുന്നു, അല്ലാഹു. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- അല്ലാഹുവെ അനുസരിക്കുക, ദൂതനെ അനുസരിക്കുക; എന്നാൽ നിങ്ങൾ പിന്തിരിഞ്ഞാൽ, അവന്റെ ചുമതല. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- അവർക്ക് അവരുടെ രക്ഷിതാവിന്റെ അടുക്കൽ അവരുടെ പ്രതിഫലമുണ്ട്, അവർക്ക് യാതൊരു ഭയവുമില്ല, അവർ. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- അവർ പറഞ്ഞു: "ഞങ്ങൾ അസ്ഥികളും പൊടിയുമായിത്തീർന്നാൽ, ഞങ്ങൾ പുതിയ സൃഷ്ടിയായി ഉയിർത്തെഴുന്നേൽക്കുമോ?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- അവർ അല്ലാഹുവെക്കൂടാതെ സ്വന്തത്തിന് യാതൊരു രക്ഷാധികാരിയെയും സഹായിയെയും കണ്ടെത്തുന്നില്ല. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "നീ എത്രകാലം താമസിച്ചു?" അവൻ പറഞ്ഞു: "ഞാൻ ഒരു ദിവസം അല്ലെങ്കിൽ ഒരു ദിവസത്തിന്റെ കുറച്ചു ഭാഗം താമസിച്ചു." അവൻ പറഞ്ഞു. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ഉയിർത്തെഴുന്നേൽപ്പിന്റെ നാളുവരെ ശാശ്വതമായി, അല്ലാഹുവെക്കൂടാതെ നിങ്ങൾക്ക് അത് നൽകാൻ കഴിയുന്ന ദൈവം ആരാണ്? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- വല്ലവനും സൽക്കർമ്മം ചെയ്യുന്നുവെങ്കിൽ, പുരുഷനായാലും സ്ത്രീയായാലും, അവൻ വിശ്വാസിയാണെങ്കിൽ. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ നിന്ന് തടയുകയും അത് വളഞ്ഞതാക്കാൻ ആഗ്രഹിക്കുകയും ചെയ്യുന്നവർ, അവർ പരലോകത്തെ. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- നിങ്ങൾ ഇച്ഛിക്കുന്നിടത്ത് ഭക്ഷിക്കുക, എന്നാൽ ഈ വൃക്ഷത്തെ സമീപിക്കരുത്, അല്ലെങ്കിൽ നിങ്ങൾ അക്രമികളാകും. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- പറയുക: "എന്റെ ജനങ്ങളേ! നിങ്ങളുടെ നിലയിൽ പ്രവർത്തിക്കുക, ഞാനും പ്രവർത്തിക്കുന്നു, ഉടൻ നിങ്ങൾ അറിയും." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- തീർച്ചയായും, നഷ്ടപ്പെട്ടവർ ഉയിർത്തെഴുന്നേൽപ്പിന്റെ നാളിൽ സ്വയവും കുടുംബവും നഷ്ടപ്പെടുത്തിയവരാണ്, ഓർക്കുക. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ആർ സൻമാർഗ്ഗം പ്രാപിക്കുന്നുവോ, അവൻ സ്വന്തം നന്മയ്ക്കായി പ്രാപിക്കുന്നു; ആർ വഴിതെറ്റുന്നുവോ, അവൻ സ്വന്തം നാശത്തിനായി തെറ്റുന്നു; കൂടാതെ. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- അവിശ്വാസികൾ പറയുന്നു: "അവന്റെ രക്ഷിതാവിങ്കൽ നിന്ന് എന്തുകൊണ്ട് ഒരു ദൃഷ്ടാന്തം അവന് അവതരിപ്പിക്കപ്പെട്ടില്ല?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- അവൻ നിങ്ങൾക്ക് രാത്രിയെ വിശ്രമത്തിനും പകലിനെ കാണാനും ആക്കിത്തന്നു, തീർച്ചയായും. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- യാതൊരു വ്യാപാരവും സൗഹൃദവും ഇല്ലാത്ത ഒരു ദിനം വരുന്നതിന് മുമ്പ്. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- അവരുടെ കൂട്ടുകാരന് യാതൊരു ഭ്രാന്തുമില്ലെന്ന് അവർ ചിന്തിക്കട്ടെ; അവൻ ഒരു താക്കീതുകാരൻ മാത്രമാണ്. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- അവർ അവയിൽ ശാശ്വതമായി കഴിയും, ശിക്ഷ അവർക്ക് ലഘൂകരിക്കപ്പെടുകയില്ല, അവർക്ക് അവധി നൽകപ്പെടുകയുമില്ല. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ഞങ്ങൾ അവരിൽ ചിലർക്ക് ആസ്വദിക്കാൻ നൽകിയതിലേക്ക് നിന്റെ കണ്ണുകൾ ഉയർത്തരുത്. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ജനങ്ങൾക്ക് അവരുടെ വസ്തുക്കളിൽ കുറവുവരുത്തരുത്, ഭൂമിയിൽ നാശം വിതയ്ക്കരുത്. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- അവൻ ജനിച്ച ദിവസത്തിലും, മരിക്കുന്ന ദിവസത്തിലും, ജീവനോടെ ഉയിർത്തെഴുന്നേൽക്കുന്ന ദിവസത്തിലും അവന് സമാധാനം. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- എന്റെ ജനങ്ങളേ! നിങ്ങളുടെ നിലയിൽ പ്രവർത്തിക്കുക, ഞാനും പ്രവർത്തിക്കുന്നു, ഉടൻ ആരെന്ന് നിങ്ങൾ അറിയും. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ഒരു ദൂതനും അല്ലാഹുവിന്റെ അനുവാദമില്ലാതെ ഒരു ദൃഷ്ടാന്തവും കൊണ്ടുവരാൻ കഴിയില്ല. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- പിന്നീട് ഓരോ ആത്മാവിനും താൻ സമ്പാദിച്ചതിന്റെ പൂർണ്ണ പ്രതിഫലം നൽകപ്പെടും, അവരോട് അക്രമം ചെയ്യപ്പെടുകയുമില്ല. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- പുരുഷനായാലും സ്ത്രീയായാലും, അവൻ വിശ്വാസിയാണെങ്കിൽ, അവർ സ്വർഗത്തിൽ പ്രവേശിക്കും. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- അവൻ ഒരു സന്താനത്തെ സ്വീകരിക്കുകയും രാജ്യാധികാരത്തിൽ ഒരു പങ്കാളിയുമില്ല. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- അല്ലാഹു ആരെ സൻമാർഗ്ഗത്തിലാക്കുന്നുവോ, അവൻ സൻമാർഗ്ഗം പ്രാപിച്ചവനാണ്; ആരെ വഴിതെറ്റിക്കുന്നുവോ. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- അവർ നിനക്ക് എങ്ങനെ ഉദാഹരണങ്ങൾ നൽകുന്നുവെന്ന് നോക്കുക, അവർ വഴിതെറ്റി, ഒരു വഴിയും കണ്ടെത്തുന്നില്ല. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- പറയുക: "ഞാൻ എന്റെ രക്ഷിതാവിനെ ധിക്കരിച്ചാൽ മഹത്തായ ദിനത്തിലെ ശിക്ഷയെ ഭയപ്പെടുന്നു." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- അവർ ഇരുവരുടെയും ലജ്ജാസ്ഥാനങ്ങൾ വെളിപ്പെട്ടു, അവർ സ്വർഗത്തിലെ ഇലകൾ കൊണ്ട് മറയ്ക്കാൻ തുടങ്ങി. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- അല്ലാഹുവിനെക്കൂടാതെ നിങ്ങൾക്ക് വിളിക്കാവുന്നവരെ വിളിക്കുക, നിങ്ങൾ സത്യവാന്മാരാണെങ്കിൽ. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- ഭൂമിയിലുള്ളതെല്ലാം അതിനോടൊപ്പം തുല്യമായതും, അതുപയോഗിച്ച് വീണ്ടെടുക്കാൻ. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ഞങ്ങൾ നിങ്ങൾക്ക് നൽകിയത് ശക്തിയായി പിടിക്കുക, അതിലുള്ളത് ഓർക്കുക, നിങ്ങൾ സൂക്ഷ്മത പാലിക്കാൻ. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ലോകരിൽ ആരും നിങ്ങൾക്ക് മുമ്പ് ചെയ്യാത്ത ആ നീചകൃത്യം നിങ്ങൾ ചെയ്യുകയാണോ? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അല്ലാഹുവിന്റേതാണ്, അല്ലാഹു. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- അവർ ചെയ്ത തിന്മകൾ അവർക്ക് ബാധിച്ചു, അവർ പരിഹസിച്ചുകൊണ്ടിരുന്നത് അവരെ വലയം ചെയ്തു. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- നിങ്ങളിൽ നിന്നുതന്നെ ഒരു ദൂതൻ, അവൻ നിങ്ങൾക്ക് നമ്മുടെ വചനങ്ങൾ വായിച്ചുകേൾപ്പിക്കുകയും നിങ്ങളെ ശുദ്ധീകരിക്കുകയും വേദവും യുക്തിയും പഠിപ്പിക്കുകയും ചെയ്യുന്നു. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- അതിൽ നിന്ന് പന്ത്രണ്ട് ഉറവകൾ പൊട്ടിയൊഴുകി; ഓരോ സമുദായവും തങ്ങളുടെ കുടിവെള്ള സ്ഥലം അറിഞ്ഞു. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- ഊഹം മാത്രം, തീർച്ചയായും ഊഹം സത്യത്തെ സംബന്ധിച്ച് യാതൊരു ഉപയോഗവുമില്ല. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- ഞാൻ അവനെ രൂപപ്പെടുത്തി എന്റെ ആത്മാവിൽ നിന്ന് അവനിൽ ഊതുമ്പോൾ, നിങ്ങൾ അവന് സുജൂദ് ചെയ്യുക. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- ഈ ലോകത്തിലെ നല്ല അന്ത്യം ആർക്കാണ്? തീർച്ചയായും, അക്രമികൾ വിജയിക്കുകയില്ല. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിച്ചവൻ, അവരെപ്പോലെ സൃഷ്ടിക്കാൻ ശക്തനാണ്. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- വിശ്വാസികളായ പുരുഷന്മാർക്കും വിശ്വാസികളായ സ്ത്രീകൾക്കും താഴ്ഭാഗത്ത് നദികൾ ഒഴുകുന്ന സ്വർഗീയാരാമങ്ങൾ, അവയിൽ അവർ ശാശ്വതമായി കഴിയും. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- അവരോട് ആകാശങ്ങളും ഭൂമിയും സൃഷ്ടിച്ചത് ആരാണെന്ന് ചോദിച്ചാൽ, അവർ തീർച്ചയായും "അല്ലാഹു" എന്ന് പറയും; പറയുക. (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- തീർച്ചയായും, ഈ ഖുർആനിൽ ഞങ്ങൾ മനുഷ്യർക്ക് എല്ലാത്തരം ഉദാഹരണങ്ങളും നൽകിയിരിക്കുന്നു. (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- നമ്മുടെ ദൂതന്മാർ ലൂത്വിന്റെ അടുത്ത് വന്നപ്പോൾ, അവൻ അവരെപ്പറ്റി വിഷമിക്കുകയും മനസ്സിടുങ്ങുകയും ചെയ്തു, പറഞ്ഞു. (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- മലക്കുകളോട് ഞങ്ങൾ "ആദമിന് സുജൂദ് ചെയ്യുവിൻ" എന്ന് പറഞ്ഞപ്പോൾ, അവർ സുജൂദ് ചെയ്തു, ഇബ്ലീസ് ഒഴികെ, അവൻ നിഷേധിച്ചു. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- ഭൂമിയെ ഞങ്ങൾ വിരിച്ചു, അതിൽ ഉറച്ച പർവ്വതങ്ങൾ ഇട്ടു, അതിൽ എല്ലാത്തരം മനോഹരമായവ മുളപ്പിച്ചു. (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
- അവർ അല്ലാഹുവെ വിളിച്ചു, മതത്തെ അവന് സമർപ്പിച്ചുകൊണ്ട്; എന്നാൽ അവൻ അവരെ കരയിലേക്ക് രക്ഷിച്ചപ്പോൾ. (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
- അവർക്ക് ചുട്ടുതിളക്കുന്ന വെള്ളത്തിൽ നിന്നുള്ള പാനീയവും അവരുടെ അവിശ്വാസം നിമിത്തം വേദനാജനകമായ ശിക്ഷയുമുണ്ട്. (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
- അല്ലാഹുവിനെക്കൂടാതെ ഞങ്ങൾക്ക് പ്രയോജനമോ ദോഷമോ ചെയ്യാത്തതിനെ ഞങ്ങൾ വിളിക്കുമോ? (أَنَدْعُو مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106
- അല്ലാഹു ആകാശങ്ങളിലും ഭൂമിയിലുമുള്ളതെല്ലാം അറിയുന്നു. (أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 5:97; 58:7
""";
